pthread_mutex_t shared_lock;
int status;

// Declaration and Dynamic Initialization
status = pthread_mutex_init(&shared_lock, NULL);

// Acquire Lock (Blocking)
status = pthread_mutex_lock(&shared_lock);

// Critical Section
// ... shared data access ...

// Release Lock
status = pthread_mutex_unlock(&shared_lock);

// Non-blocking Acquire attempt
status = pthread_mutex_trylock(&shared_lock);

// Cleanup (if resources persist)
status = pthread_mutex_destroy(&shared_lock);

